DROP TABLE IF EXISTS `notice`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `notice` (
  `notice_id` int unsigned NOT NULL AUTO_INCREMENT COMMENT '公告编号',
  `title` varchar(100) NOT NULL COMMENT '公告标题',
  `content` text NOT NULL COMMENT '公告内容',
  `notice_type` varchar(10) NOT NULL COMMENT '公告类型',
  `scope` varchar(20) NOT NULL DEFAULT '全院' COMMENT '发布范围',
  `publisher_id` int unsigned NOT NULL COMMENT '发布人用户编号',
  `publish_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '发布时间',
  `is_top` tinyint(1) NOT NULL DEFAULT '0' COMMENT '置顶标记',
  PRIMARY KEY (`notice_id`),
  KEY `fk_notice_user` (`publisher_id`),
  KEY `idx_notice_scope` (`scope`,`publish_time`),
  CONSTRAINT `fk_notice_user` FOREIGN KEY (`publisher_id`) REFERENCES `sys_user` (`user_id`) ON DELETE RESTRICT,
  CONSTRAINT `ck_notice_type` CHECK ((`notice_type` in (_utf8mb4'通知',_utf8mb4'公告',_utf8mb4'模板',_utf8mb4'政策')))
) ENGINE=InnoDB AUTO_INCREMENT=9 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='公告表';
/*!40101 SET character_set_client = @saved_cs_client */;

