LOCK TABLES `notice` WRITE;
/*!40000 ALTER TABLE `notice` DISABLE KEYS */;
INSERT INTO `notice` VALUES (1,'关于 2026 届毕业设计选题工作的通知','2026 届毕业设计选题工作于 9 月 15 日启动，请各位同学登录系统查看已发布题目，按志愿顺序提交选题申请，每名学生最多填报 3 个志愿。选题截止时间为 9 月 30 日 18:00。','通知','全院',2,'2026-09-10 09:00:00',1),(2,'2026 届毕业设计任务书下达要求','指导教师须在 9 月 30 日前完成学生任务书下达，任务书应明确设计任务、技术要求与进度安排；学生须在 10 月 10 日前登录系统确认接收。逾期未确认的课题将在进度跟踪中标记为异常。','通知','教师',2,'2026-09-12 10:30:00',1),(3,'开题报告撰写规范与模板','开题报告应包含研究背景与意义、国内外研究现状、研究内容与方法、进度安排、参考文献等部分，字数不少于 3000 字。模板请在附件中下载，格式不符合要求的材料将被退回。','模板','学生',2,'2026-10-08 14:00:00',0),(4,'关于开题报告阶段截止时间的提醒','开题报告阶段将于 2026 年 12 月 20 日 23:59 截止，请尚未提交的同学抓紧时间。逾期未提交且未办理延期申请的，按学校毕业设计管理规定处理。','通知','学生',2,'2026-10-20 08:30:00',0),(5,'毕业设计中期检查安排','中期检查阶段为 2026 年 12 月 21 日至 2027 年 3 月 10 日，指导教师须组织学生进行中期汇报，并在系统中填写中期检查意见。检查不合格的课题须限期整改。','通知','全院',2,'2026-10-21 09:15:00',0),(6,'论文查重与学术不端处理办法','毕业论文须通过学校指定的查重系统检测，总文字复制比不得高于 20%。检测不合格的论文须修改后重新检测，两次检测仍不合格者按学术不端处理。','政策','全院',1,'2026-09-05 11:00:00',0),(7,'2025 届毕业设计成绩查询开放','2025 届毕业设计成绩已发布，学生可登录系统在「成绩与答辩」中查询本人过程成绩、评阅成绩、答辩成绩、总评成绩与等级。对成绩有异议的，可在发布后 5 个工作日内向所在学院提出复核申请。','通知','学生',2,'2025-06-12 10:00:00',0),(8,'2025 届优秀毕业设计评选结果公示','经各答辩小组推荐、学院评审，2025 届共评选优秀毕业设计 3 项，现予公示。公示期为 5 个工作日，如有异议请向教学办公室反映。','公告','全院',2,'2025-06-20 15:30:00',0);
/*!40000 ALTER TABLE `notice` ENABLE KEYS */;
UNLOCK TABLES;

