CREATE TABLE `operation_log` (
  `log_id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '日志编号',
  `user_id` int unsigned DEFAULT NULL COMMENT '用户编号',
  `op_type` varchar(10) NOT NULL COMMENT '操作类型',
  `op_module` varchar(30) NOT NULL COMMENT '操作模块',
  `description` varchar(200) DEFAULT NULL COMMENT '操作描述',
  `op_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '操作时间',
  `ip` varchar(45) DEFAULT NULL COMMENT 'IP 地址',
  PRIMARY KEY (`log_id`),
  KEY `idx_log_user_time` (`user_id`,`op_time`),
  CONSTRAINT `fk_log_user` FOREIGN KEY (`user_id`) REFERENCES `sys_user` (`user_id`) ON DELETE SET NULL,
  CONSTRAINT `ck_log_type` CHECK ((`op_type` in (_utf8mb4'登录',_utf8mb4'查询',_utf8mb4'新增',_utf8mb4'修改',_utf8mb4'删除')))
) ENGINE=InnoDB AUTO_INCREMENT=102 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='操作日志表';
/*!40101 SET character_set_client = @saved_cs_client */;

