--
-- Table structure for table `project`
--

DROP TABLE IF EXISTS `project`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `project` (
  `project_no` char(14) NOT NULL COMMENT '课题编号',
  `student_no` char(12) NOT NULL COMMENT '学号',
  `topic_no` char(12) NOT NULL COMMENT '题目编号',
  `teacher_no` char(8) NOT NULL COMMENT '指导教师工号',
  `current_stage` smallint unsigned DEFAULT NULL COMMENT '当前阶段编号',
  `project_status` varchar(10) NOT NULL DEFAULT '进行中' COMMENT '课题状态',
  `start_date` date NOT NULL COMMENT '开始日期',
  `end_date` date DEFAULT NULL COMMENT '结束日期',
  PRIMARY KEY (`project_no`),
  UNIQUE KEY `uk_project_student` (`student_no`),
  KEY `fk_project_topic` (`topic_no`),
  KEY `fk_project_stage` (`current_stage`),
  KEY `idx_project_teacher` (`teacher_no`),
  CONSTRAINT `fk_project_stage` FOREIGN KEY (`current_stage`) REFERENCES `stage` (`stage_id`),
  CONSTRAINT `fk_project_student` FOREIGN KEY (`student_no`) REFERENCES `student` (`student_no`) ON DELETE CASCADE,
  CONSTRAINT `fk_project_teacher` FOREIGN KEY (`teacher_no`) REFERENCES `teacher` (`teacher_no`) ON DELETE RESTRICT,
  CONSTRAINT `fk_project_topic` FOREIGN KEY (`topic_no`) REFERENCES `topic` (`topic_no`) ON DELETE RESTRICT,
  CONSTRAINT `ck_project_date` CHECK (((`end_date` is null) or (`end_date` >= `start_date`))),
  CONSTRAINT `ck_project_status` CHECK ((`project_status` in (_utf8mb4'进行中',_utf8mb4'已答辩',_utf8mb4'已归档')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='课题表';
/*!40101 SET character_set_client = @saved_cs_client */;

