/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER `trg_student_au` AFTER UPDATE ON `student` FOR EACH ROW BEGIN
    IF NEW.class_no <> OLD.class_no THEN
        UPDATE class_info
           SET student_count = student_count - 1
         WHERE class_no = OLD.class_no;
        UPDATE class_info
           SET student_count = student_count + 1
         WHERE class_no = NEW.class_no;
    END IF;
END */;;
DELIMITER ;
