CREATE TABLE `submission` (
  `submission_id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '材料编号',
  `project_no` char(14) NOT NULL COMMENT '课题编号',
  `stage_id` smallint unsigned NOT NULL COMMENT '阶段编号',
  `version` smallint unsigned NOT NULL COMMENT '版本号',
  `file_path` varchar(255) NOT NULL COMMENT '文件路径',
  `submit_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '提交时间',
  `audit_status` varchar(10) NOT NULL DEFAULT '待评阅' COMMENT '审核状态',
  PRIMARY KEY (`submission_id`),
  UNIQUE KEY `uk_sub_version` (`project_no`,`stage_id`,`version`),
  KEY `fk_sub_stage` (`stage_id`),
  KEY `idx_sub_project` (`project_no`,`stage_id`,`version`),
  CONSTRAINT `fk_sub_project` FOREIGN KEY (`project_no`) REFERENCES `project` (`project_no`) ON DELETE CASCADE,
  CONSTRAINT `fk_sub_stage` FOREIGN KEY (`stage_id`) REFERENCES `stage` (`stage_id`) ON DELETE RESTRICT,
  CONSTRAINT `ck_sub_status` CHECK ((`audit_status` in (_utf8mb4'待评阅',_utf8mb4'通过',_utf8mb4'修改后通过',_utf8mb4'不通过'))),
  CONSTRAINT `ck_sub_version` CHECK ((`version` >= 1))
) ENGINE=InnoDB AUTO_INCREMENT=103 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='提交材料表';
