DROP TABLE IF EXISTS `task_book`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `task_book` (
  `task_id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '任务书编号',
  `project_no` char(14) NOT NULL COMMENT '课题编号',
  `design_task` text NOT NULL COMMENT '设计任务',
  `tech_requirement` text COMMENT '技术要求',
  `schedule` text COMMENT '进度安排',
  `issue_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '下达时间',
  `confirm_status` varchar(10) NOT NULL DEFAULT '未确认' COMMENT '确认状态',
  PRIMARY KEY (`task_id`),
  UNIQUE KEY `uk_task_project` (`project_no`),
  CONSTRAINT `fk_task_project` FOREIGN KEY (`project_no`) REFERENCES `project` (`project_no`) ON DELETE CASCADE,
  CONSTRAINT `ck_task_status` CHECK ((`confirm_status` in (_utf8mb4'未确认',_utf8mb4'已确认')))
) ENGINE=InnoDB AUTO_INCREMENT=31 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='任务书表';
