--
-- Table structure for table `teacher`
--

DROP TABLE IF EXISTS `teacher`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `teacher` (
  `teacher_no` char(8) NOT NULL COMMENT '工号',
  `user_id` int unsigned DEFAULT NULL COMMENT '用户编号',
  `name` varchar(20) NOT NULL COMMENT '姓名',
  `gender` char(2) NOT NULL COMMENT '性别',
  `title` varchar(10) NOT NULL COMMENT '职称',
  `dept_no` char(4) NOT NULL COMMENT '所属院系编号',
  `research_field` varchar(100) DEFAULT NULL COMMENT '研究方向',
  `phone` char(11) DEFAULT NULL COMMENT '联系电话',
  `email` varchar(50) DEFAULT NULL COMMENT '电子邮箱',
  `max_students` tinyint unsigned NOT NULL DEFAULT '5' COMMENT '可指导人数',
  `introduction` varchar(500) DEFAULT NULL COMMENT '个人简介',
  PRIMARY KEY (`teacher_no`),
  UNIQUE KEY `uk_teacher_user` (`user_id`),
  KEY `fk_teacher_dept` (`dept_no`),
  CONSTRAINT `fk_teacher_dept` FOREIGN KEY (`dept_no`) REFERENCES `department` (`dept_no`),
  CONSTRAINT `fk_teacher_user` FOREIGN KEY (`user_id`) REFERENCES `sys_user` (`user_id`) ON DELETE SET NULL,
  CONSTRAINT `ck_teacher_gender` CHECK ((`gender` in (_utf8mb4'男',_utf8mb4'女'))),
  CONSTRAINT `ck_teacher_max` CHECK ((`max_students` between 1 and 10)),
  CONSTRAINT `ck_teacher_title` CHECK ((`title` in (_utf8mb4'助教',_utf8mb4'讲师',_utf8mb4'副教授',_utf8mb4'教授')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='指导教师表';
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `teacher`
--

LOCK TABLES `teacher` WRITE;
/*!40000 ALTER TABLE `teacher` DISABLE KEYS */;
