-- Table structure for table `topic`
--

DROP TABLE IF EXISTS `topic`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `topic` (
  `topic_no` char(12) NOT NULL COMMENT '题目编号',
  `topic_name` varchar(100) NOT NULL COMMENT '题目名称',
  `topic_type` varchar(10) NOT NULL COMMENT '题目类型',
  `research_field` varchar(100) DEFAULT NULL COMMENT '研究方向',
  `difficulty` varchar(6) NOT NULL COMMENT '难度',
  `applicant_no` char(8) NOT NULL COMMENT '申报人工号',
  `capacity` tinyint unsigned NOT NULL DEFAULT '1' COMMENT '可选人数',
  `cohort` char(4) NOT NULL COMMENT '所属届别',
  `status` varchar(10) NOT NULL DEFAULT '待审核' COMMENT '题目状态',
  `audit_opinion` varchar(200) DEFAULT NULL COMMENT '审核意见',
  PRIMARY KEY (`topic_no`),
  KEY `idx_topic_cohort` (`cohort`,`status`),
  KEY `idx_topic_applicant` (`applicant_no`),
  CONSTRAINT `fk_topic_teacher` FOREIGN KEY (`applicant_no`) REFERENCES `teacher` (`teacher_no`),
  CONSTRAINT `ck_topic_capacity` CHECK ((`capacity` between 1 and 5)),
  CONSTRAINT `ck_topic_diff` CHECK ((`difficulty` in (_utf8mb4'易',_utf8mb4'中',_utf8mb4'难'))),
  CONSTRAINT `ck_topic_status` CHECK ((`status` in (_utf8mb4'待审核',_utf8mb4'已发布',_utf8mb4'未通过',_utf8mb4'已停用'))),
  CONSTRAINT `ck_topic_type` CHECK ((`topic_type` in (_utf8mb4'工程设计',_utf8mb4'软件开发',_utf8mb4'理论研究',_utf8mb4'其他')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='题目表';
/*!40101 SET character_set_client = @saved_cs_client */;

