CREATE DEFINER=`root`@`localhost` FUNCTION `fn_score_level`(p_total DECIMAL(5,2)) RETURNS varchar(10) CHARSET utf8mb4 COLLATE utf8mb4_general_ci
    DETERMINISTIC
BEGIN
    IF p_total IS NULL THEN
        RETURN NULL;
    END IF;
    IF p_total >= 90 THEN RETURN '优秀';
    ELSEIF p_total >= 80 THEN RETURN '良好';
    ELSEIF p_total >= 70 THEN RETURN '中等';
    ELSEIF p_total >= 60 THEN RETURN '及格';
    ELSE RETURN '不及格';
    END IF;
END ;;
